// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address nonOwner) public {
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != c.owner());
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 initialOwnerBalance = c.owner().balance;
        vm.prank(nonOwner);
        try c.withdraw(amount) { } catch { }
        bool invariantHolds = (c.owner().balance == initialOwnerBalance) && (address(c).balance == amount);
        assertTrue(invariantHolds);
    }
}
